fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    // Determine lengths
    let m = a.len();
    let n = b.len();
    let out_len = if m > n { m } else { n };

    // Prepare output vectors with capacity out_len
    let mut out_a = Vec::with_capacity(out_len);
    let mut out_b = Vec::with_capacity(out_len);

    // For each index i, choose element from a and b according to broadcast rules
    for i in 0..out_len {
        let val_a = if m == 1 { a[0] } else { a[i] };
        let val_b = if n == 1 { b[0] } else { b[i] };
        out_a.push(val_a);
        out_b.push(val_b);
    }

    (out_a, out_b)
}